{
  "Count": 16,
  "Tools": [
    {
      "Name": "DemoModule_Add",
      "Description": "两个整数相加,返回和\n示例: DemoModule.Add a=1 b=1",
      "InputSchema": {
        "type": "object",
        "properties": {
          "a": {
            "type": "integer",
            "description": "第一个加数"
          },
          "b": {
            "type": "integer",
            "description": "第二个加数"
          }
        },
        "required": [
          "a",
          "b"
        ]
      }
    },
    {
      "Name": "DemoModule_Now",
      "Description": "返回当前时间和机器名(演示静态方法与对象返回值的 JSON 回显)\n示例: DemoModule.Now",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "DemoModule_Reverse",
      "Description": "把字符串反转\n示例: DemoModule.Reverse text=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "要反转的字符串"
          }
        },
        "required": [
          "text"
        ]
      }
    },
    {
      "Name": "DemoModule_SayHello",
      "Description": "向指定的人问好(演示异步方法与默认参数)\n示例: DemoModule.SayHello name=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "要问候的名字,缺省为 World",
            "default": "World"
          }
        }
      }
    },
    {
      "Name": "HelloWorld_Say",
      "Description": "返回固定问候文本，不产生任何外部副作用\n示例: HelloWorld.Say",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "ProjectPulse_Largest",
      "Description": "列出一个 OHS 工作树中最大的文件\n示例: ProjectPulse.Largest name=文本 limit=1 minMb=1.5 includeGenerated=true",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记工作树名称，例如 2026-020-OneHistoryStudio"
          },
          "limit": {
            "type": "integer",
            "description": "最多返回文件数，范围 1~200",
            "default": 20
          },
          "minMb": {
            "type": "number",
            "description": "最小体积 MB，范围 0~1048576",
            "default": 1
          },
          "includeGenerated": {
            "type": "boolean",
            "description": "是否包含 bin、obj、.vs、node_modules 等生成目录",
            "default": false
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "ProjectPulse_Recent",
      "Description": "列出一个 OHS 工作树最近修改的文件\n示例: ProjectPulse.Recent name=文本 days=1 limit=1 includeGenerated=true",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记工作树名称，例如 2026-020-OneHistoryStudio"
          },
          "days": {
            "type": "integer",
            "description": "回看天数，范围 1~3650",
            "default": 7
          },
          "limit": {
            "type": "integer",
            "description": "最多返回文件数，范围 1~200",
            "default": 30
          },
          "includeGenerated": {
            "type": "boolean",
            "description": "是否包含 bin、obj、.vs、node_modules 等生成目录",
            "default": false
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "ProjectPulse_Summary",
      "Description": "汇总一个 OHS 工作树的文件数量、体积、格式和一级目录热点\n示例: ProjectPulse.Summary name=文本 includeGenerated=true top=1",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记工作树名称，例如 2026-020-OneHistoryStudio"
          },
          "includeGenerated": {
            "type": "boolean",
            "description": "是否包含 bin、obj、.vs、node_modules 等生成目录",
            "default": false
          },
          "top": {
            "type": "integer",
            "description": "最多返回多少项格式和一级目录统计，范围 1~50",
            "default": 10
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "ToolAlpha_Ver",
      "Description": "返回本模块槽内 SharedDep 依赖的版本标识\n示例: ToolAlpha.Ver",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "ToolKit_Base64Encode",
      "Description": "把 UTF-8 文本编码为 Base64\n示例: ToolKit.Base64Encode text=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "要编码的文本"
          }
        },
        "required": [
          "text"
        ]
      }
    },
    {
      "Name": "ToolKit_NewGuid",
      "Description": "生成一个新 GUID\n示例: ToolKit.NewGuid",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "ToolKit_Now",
      "Description": "当前本地时间与 Unix 秒\n示例: ToolKit.Now",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "ToolKit_Sha256",
      "Description": "计算文本的 SHA-256(十六进制大写)\n示例: ToolKit.Sha256 text=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "要哈希的文本"
          }
        },
        "required": [
          "text"
        ]
      }
    },
    {
      "Name": "ToolRelay_Call",
      "Description": "通过 OHS 最新 MCP 工具目录调用一个工具，不依赖 Codex 当前任务的旧快照\n示例: ToolRelay.Call name=文本 argumentsJson=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "MCP 工具名，例如 ProjectPulse_Summary"
          },
          "argumentsJson": {
            "type": "string",
            "description": "JSON 对象字符串，默认空对象，最大 64 KiB",
            "default": "{}"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "ToolRelay_Describe",
      "Description": "实时查看一个当前可见 MCP 工具的描述和 JSON Schema\n示例: ToolRelay.Describe name=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "MCP 工具名，例如 ProjectPulse_Summary"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "ToolRelay_List",
      "Description": "实时列出 OHS 当前 MCP 策略下可见的工具\n示例: ToolRelay.List filter=文本 modulesOnly=true",
      "InputSchema": {
        "type": "object",
        "properties": {
          "filter": {
            "type": "string",
            "description": "按工具名或描述包含匹配，空字符串不过滤",
            "default": ""
          },
          "modulesOnly": {
            "type": "boolean",
            "description": "true 只返回模块工具，false 返回全部可见工具",
            "default": true
          }
        }
      }
    }
  ]
}
